export function createEffects(T,scene,surfaces){
 const particles=[],marks=[],geometry=new T.BoxGeometry(.045,.045,.045),materials={blood:new T.MeshBasicMaterial({color:'#831d25'}),dust:new T.MeshBasicMaterial({color:'#aeaaa0'}),brass:surfaces?.material('#c89b43','metal',true)||new T.MeshStandardMaterial({color:'#c89b43',metalness:.65,roughness:.35})};
 const spawn=(type,p,count=8)=>{for(let i=0;i<count;i++){if(particles.length>=140){const old=particles.shift();scene.remove(old.mesh);}const mesh=new T.Mesh(geometry,materials[type]);mesh.position.copy(p);mesh.scale.setScalar(type==='brass'?.6:1+Math.random()*1.5);scene.add(mesh);particles.push({mesh,v:new T.Vector3((Math.random()-.5)*3,1+Math.random()*2,(Math.random()-.5)*3),life:type==='brass'?1.8:.6,type});}};
 const mark=(p,blood=false)=>{if(marks.length>=100){const old=marks.shift();scene.remove(old.mesh);old.mesh.geometry.dispose();old.mesh.material.dispose();}const mesh=new T.Mesh(new T.PlaneGeometry(blood?.2:.1,blood?.3:.8),new T.MeshBasicMaterial({color:blood?'#601e23':'#262c2d',transparent:true,opacity:.6,depthWrite:false}));mesh.rotation.x=-Math.PI/2;mesh.position.copy(p);mesh.position.y+=.012;scene.add(mesh);marks.push({mesh,life:blood?18:14});};
 return{spawn,mark,tick(dt,height){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.v.y-=12*dt;p.mesh.position.addScaledVector(p.v,dt);p.mesh.rotation.x+=dt*8;if(p.mesh.position.y<height(p.mesh.position.x,p.mesh.position.z)){if(p.type==='blood')mark(new T.Vector3(p.mesh.position.x,height(p.mesh.position.x,p.mesh.position.z),p.mesh.position.z),true);p.life=0;}if(p.life<=0){scene.remove(p.mesh);particles.splice(i,1);}}for(let i=marks.length-1;i>=0;i--){marks[i].life-=dt;marks[i].mesh.material.opacity=Math.min(.6,marks[i].life*.12);if(marks[i].life<=0){scene.remove(marks[i].mesh);marks[i].mesh.geometry.dispose();marks[i].mesh.material.dispose();marks.splice(i,1);}}}};
}
